import asyncio
import json
import aiohttp

async def main():
    async with aiohttp.ClientSession() as session:
        # Get page target
        async with session.get("http://localhost:9222/json") as resp:
            targets = await resp.json()
            ws_url = None
            for t in targets:
                if t.get("type") == "page":
                    ws_url = t["webSocketDebuggerUrl"]
                    break
            if not ws_url:
                # Try first target
                ws_url = targets[0]["webSocketDebuggerUrl"]

        async with aiohttp.ClientSession() as session2:
            async with session2.ws_connect(ws_url) as ws:
                # Navigate to LinkedIn feed
                await ws.send_json({"id": 1, "method": "Page.navigate", "params": {"url": "https://www.linkedin.com/feed/"}})
                while True:
                    msg = await ws.receive()
                    if msg.type == aiohttp.WSMsgType.TEXT:
                        data = json.loads(msg.data)
                        if data.get("id") == 1 and "result" in data:
                            break

                # Wait for page to load
                await asyncio.sleep(5)

                # Click "Start a post" button - find by role or text
                result = await ws.send_json({
                    "id": 2,
                    "method": "Runtime.evaluate",
                    "params": {
                        "expression": """
                            (() => {
                                // Find the Start a post input
                                const inputs = document.querySelectorAll('input[aria-label="Start a post"]');
                                if (inputs.length > 0) {
                                    inputs[0].click();
                                    return 'Clicked Start a post';
                                }
                                // Try button with text
                                const buttons = Array.from(document.querySelectorAll('button, span'));
                                for (const btn of buttons) {
                                    if (btn.textContent.includes('Start a post')) {
                                        btn.click();
                                        return 'Clicked by text';
                                    }
                                }
                                return 'Not found';
                            })()
                        """
                    }
                })
                while True:
                    msg = await ws.receive()
                    if msg.type == aiohttp.WSMsgType.TEXT:
                        data = json.loads(msg.data)
                        if data.get("id") == 2:
                            print(f"Click result: {data}")
                            break

                # Wait for dialog to open
                await asyncio.sleep(3)

                # Type the post content
                post_text = """One thing I've learned working in marketing + analytics: the best campaigns don't start with creative. They start with a question.

What does our audience actually care about? Where are they dropping off? Which message moves them to act?

Data doesn't replace creativity — it sharpens it. When you know who you're talking to and what they need, the messaging becomes effortless.

The biggest mistake I see? Teams falling in love with their idea before validating it with real customer signals.

What's one data insight that completely changed how you approach marketing?"""

                result = await ws.send_json({
                    "id": 3,
                    "method": "Runtime.evaluate",
                    "params": {
                        "expression": f"""
                            (() => {{
                                // Find the editor - usually a div.ql-editor or textarea
                                const editors = document.querySelectorAll('div[contenteditable="true"], .ql-editor, [class*="editor"]');
                                for (const ed of editors) {{
                                    if (ed.closest('[class*="modal"], [class*="dialog"], [class*="share"]')) {{
                                        ed.focus();
                                        // Type character by character to simulate real input
                                        const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
                                        nativeInputValueSetter.call(ed, {json.dumps(post_text)});
                                        ed.dispatchEvent(new Event('input', {{ bubbles: true }}));
                                        return 'Text entered';
                                    }}
                                }}
                                // Fallback: find any contenteditable in the modal
                                const modals = document.querySelectorAll('[class*="modal"], [class*="dialog"]');
                                for (const m of modals) {{
                                    const ce = m.querySelector('[contenteditable="true"]');
                                    if (ce) {{
                                        ce.focus();
                                        const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
                                        nativeInputValueSetter.call(ce, {json.dumps(post_text)});
                                        ce.dispatchEvent(new Event('input', {{ bubbles: true }}));
                                        return 'Text entered in modal';
                                    }}
                                }}
                                return 'Editor not found';
                            }})()
                        """
                    }
                })
                while True:
                    msg = await ws.receive()
                    if msg.type == aiohttp.WSMsgType.TEXT:
                        data = json.loads(msg.data)
                        if data.get("id") == 3:
                            print(f"Text result: {data}")
                            break

                # Wait for text to appear
                await asyncio.sleep(2)

                # Click the Post button - use exact match
                result = await ws.send_json({
                    "id": 4,
                    "method": "Runtime.evaluate",
                    "params": {
                        "expression": """
                            (() => {
                                // Find all buttons with text "Post"
                                const allBtns = document.querySelectorAll('button');
                                for (const btn of allBtns) {
                                    if (btn.textContent.trim() === 'Post' && 
                                        !btn.closest('[class*="settings"]') &&
                                        !btn.getAttribute('aria-label')?.includes('Schedule')) {
                                        btn.click();
                                        return 'Clicked Post button';
                                    }
                                }
                                // Alternative: find primary action button in share actions
                                const primaryBtn = document.querySelector('.share-actions__primary-action, [class*="primary-action"]');
                                if (primaryBtn) {
                                    primaryBtn.click();
                                    return 'Clicked primary action button';
                                }
                                return 'Post button not found';
                            })()
                        """
                    }
                })
                while True:
                    msg = await ws.receive()
                    if msg.type == aiohttp.WSMsgType.TEXT:
                        data = json.loads(msg.data)
                        if data.get("id") == 4:
                            print(f"Post result: {data}")
                            break

                # Wait for post to publish
                await asyncio.sleep(5)

                # Take a screenshot to verify
                result = await ws.send_json({
                    "id": 5,
                    "method": "Page.captureScreenshot",
                    "params": {"format": "png"}
                })
                while True:
                    msg = await ws.receive()
                    if msg.type == aiohttp.WSMsgType.TEXT:
                        data = json.loads(msg.data)
                        if data.get("id") == 5 and "result" in data:
                            import base64
                            img_data = base64.b64decode(data["result"]["data"])
                            with open("/tmp/linkedin_post_screenshot.png", "wb") as f:
                                f.write(img_data)
                            print("Screenshot saved!")
                            break

asyncio.run(main())
